import{_ as r,C as a,o,c as n,j as t,a as i,E as l,a2 as d}from"./chunks/framework.BxGh02fV.js";const E=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),u={name:"guide/index.md"};function c(p,e,g,f,m,h){const s=a("Capture");return o(),n("div",null,[e[0]||(e[0]=t("h1",{id:"introduction",tabindex:"-1"},[i("Introduction "),t("a",{class:"header-anchor",href:"#introduction","aria-label":'Permalink to "Introduction"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Effortless est une application de bureau qui conduit un projet logiciel de l'idée à la livraison, en suivant le pipe OPALE. Ce guide décrit l'édition standard, écran par écran. Les mêmes opérations sont accessibles aux agents IA : l'application est la vue humaine de ce que les agents font aussi.",-1)),l(s,{name:"dashboard",alt:"Le tableau de bord d'un workspace : phase en cours, épic, story et tâche actifs"}),e[2]||(e[2]=d('<h2 id="le-modele-mental" tabindex="-1">Le modèle mental <a class="header-anchor" href="#le-modele-mental" aria-label="Permalink to &quot;Le modèle mental&quot;">​</a></h2><p><strong>Workspace.</strong> Un workspace est un projet Effortless : un dossier qui contient <code>.effortless/</code> (les données, en JSON) et <code>blueprints/</code> (les mêmes informations, rendues en Markdown). Vous ouvrez un workspace par onglet.</p><p><strong>Projet → Épic → Story → Tâche.</strong> Le travail se découpe en quatre niveaux. Un épic regroupe des stories, une story regroupe des tâches. Un seul épic et une seule story sont actifs à la fois : c&#39;est là que se concentre le travail.</p><p><strong>Les phases OPALE.</strong> Une story traverse cinq phases :</p><ol><li><strong>O</strong> : analyse (Observer) ;</li><li><strong>P</strong> : cadrage (Positionner) ;</li><li><strong>A</strong> : spécifications (Articuler) ;</li><li><strong>L</strong> : plan (Lancer) ;</li><li><strong>E</strong> : exécution.</li></ol><p>Une story de nature <code>fix</code> saute le cadrage et démarre directement en exécution. Pour passer à la phase suivante, les documents requis de la phase courante doivent exister.</p><p><strong>Les évolutions.</strong> Le registre des évolutions est la mémoire du produit : anomalies, fonctionnalités, améliorations, découvertes, tests. Chacune a un identifiant (par exemple <code>26ANO335</code>), une criticité de 1 à 3 et un état. Des évolutions peuvent être regroupées en lot, puis graduées en épic.</p><p><strong>Décisions et questions.</strong> Les décisions (DEC-xx) et les questions ouvertes sont consignées au niveau de la story ou de l&#39;épic.</p><p><strong>Humains et agents.</strong> Un agent IA se connecte au même moteur par un serveur MCP, avec des verbes comme <code>effortless_status</code> ou <code>effortless_story_start</code>. Ce que fait l&#39;agent apparaît dans l&#39;application, et inversement.</p><div class="tip custom-block"><p class="custom-block-title">La configuration recommandée</p><p>Gardez l&#39;application ouverte, et travaillez avec un agent en ligne de commande — Claude Code, Codex ou Antigravity — <strong>lancé depuis la racine du projet</strong> (le dossier qui contient <code>effortless.json</code>). Le terminal intégré de VS Code, ouvert sur le dossier du projet, convient aussi. Voir <a href="/Effortless/agent/#travailler-au-mieux-l-agent-ouvert-a-la-racine-du-projet">Travailler au mieux</a>.</p></div><h2 id="comment-le-guide-est-organise" tabindex="-1">Comment le guide est organisé <a class="header-anchor" href="#comment-le-guide-est-organise" aria-label="Permalink to &quot;Comment le guide est organisé&quot;">​</a></h2><p>Pour commencer :</p><ul><li><a href="/Effortless/guide/first-run.html">Premier lancement</a> : l&#39;écran de démarrage et l&#39;assistant qui crée votre profil.</li><li><a href="/Effortless/guide/setup.html">Choisir son organisation</a> : le mode de travail et l&#39;organisation du code (modules, dépôts externes, sources partagées), à décider avant de démarrer.</li><li><a href="/Effortless/guide/start.html">Ouvrir un workspace</a> : le sélecteur, point d&#39;entrée.</li><li><a href="/Effortless/guide/create.html">Assistant de création</a> et <a href="/Effortless/guide/adopt.html">Reprendre un projet existant</a> : les deux parcours guidés pour démarrer un projet.</li><li><a href="/Effortless/guide/window.html">Fenêtre, barres et systray</a> : les onglets, le thème, la barre latérale, les raccourcis, et ce qui se passe quand vous fermez la fenêtre.</li></ul><p>Puis les écrans d&#39;un workspace, dans l&#39;ordre de la barre latérale :</p><ul><li><strong>Pilotage</strong> : <a href="/Effortless/guide/dashboard.html">Tableau de bord</a>.</li><li><strong>Backlog &amp; travail</strong> : <a href="/Effortless/guide/backlog.html">Backlog</a> et <a href="/Effortless/guide/tasks.html">Tâches</a>.</li><li><strong>Cadrage &amp; connaissance</strong> : <a href="/Effortless/guide/knowledge.html">Connaissance</a>.</li><li><strong>Qualité &amp; versioning</strong> : <a href="/Effortless/guide/drift.html">Dérive</a>, <a href="/Effortless/guide/git.html">Git</a>, <a href="/Effortless/guide/release.html">Livraison</a> et <a href="/Effortless/guide/modules.html">Modules</a>.</li><li>En bas de la barre latérale : <a href="/Effortless/guide/settings.html">Réglages du projet</a> et <a href="/Effortless/guide/help.html">Aide</a>.</li><li><a href="/Effortless/guide/preferences.html">Profil et préférences</a> : les réglages de l&#39;application, indépendants du projet.</li></ul><p>Chaque page décrit ce que l&#39;écran montre, puis ce que vous pouvez y faire. Quand un verbe MCP correspond, une section « Avec un agent IA » le nomme.</p>',16))])}const b=r(u,[["render",c]]);export{E as __pageData,b as default};
